// Karnaugh map for the Boolean function f(a, b, c, d) = (a + b) * (c + d)
// is the same as the Boolean function f(a, b, c, d) = a * c + a * d + b * c
// + b * d. Expanded out, this is the same as the Boolean function:
// f(a, b, c, d) = a * c + a * d + b * c + b * d.
module TopModule(
    input  a,
    input  b,
    input  c,
    input  d,
    output out
);
    wire w1 = a & c;
    wire w2 = a & d;
    wire w3 = b & c;
    wire w4 = b & d;
    assign out = w1 | w2 | w3 | w4;
endmodule

